#include "InteroceptiveSafetyModel.h"
namespace dnxr { InteroceptiveSafetyDecision InteroceptiveSafetyModel::evaluate(float resp,float hr,float stress,bool nausea,bool vertigo,bool panic,bool dis,bool stop,bool comm) const { if(stop||comm) return {InteroceptiveAction::EmergencyStop,stop?"patient_stop_requested":"communication_lost"}; if(panic||dis) return {InteroceptiveAction::Decompress,"panic_or_disorientation"}; if(nausea||vertigo||stress>0.7f||hr>130||resp>28) return {InteroceptiveAction::RealityAnchor,"physiology_instability"}; if(stress>0.4f) return {InteroceptiveAction::ReduceIntensity,"stress_rising"}; return {}; } }
